export const SIZE=112,HEIGHT=40,HALF=SIZE/2,WATER=5;
export const BLOCK={AIR:0,GRASS:1,DIRT:2,STONE:3,WOOD:4,LEAF:5,SAND:6,IRON:7,CRYSTAL:8,PLANK:9,BRICK:10,BEDROCK:11,OBSIDIAN:12,GLOW:13};
export const items={wood:{name:'原木',color:'#987044',block:4},stone:{name:'原石',color:'#8d9291',block:3},dirt:{name:'泥土',color:'#826047',block:2},grass:{name:'草方块',color:'#708e4d',block:1},sand:{name:'沙子',color:'#d6cba7',block:6},leaf:{name:'树叶',color:'#547546',block:5},ore:{name:'铁矿石',color:'#aa8c72',block:7},crystal:{name:'星辉水晶',color:'#8ccacf',block:8},plank:{name:'木板',color:'#bd9564',block:9},brick:{name:'石砖',color:'#77877d',block:10},pick:{name:'石镐',icon:'⛏',color:'#a9b6aa'},sword:{name:'铁剑',icon:'⚔',color:'#d7e0da'},furnace:{name:'熔炉',icon:'▣',color:'#8c9891'},iron:{name:'铁锭',color:'#d1c8ae'},sigil:{name:'星门符印',icon:'✧',color:'#c9b8f0'},food:{name:'林间浆果',icon:'●',color:'#dc9692'},torch:{name:'萤石',color:'#ebd89a',block:13}};
export const drop={1:'dirt',2:'dirt',3:'stone',4:'wood',5:'leaf',6:'sand',7:'ore',8:'crystal',9:'plank',10:'brick',13:'torch'};
export const blockNames=['空气','草地','泥土','岩石','橡木','树叶','河沙','铁矿脉','星辉水晶','橡木板','遗迹石砖','基岩','星门黑曜石','萤石'];
export const recipes=[{id:'pick',out:1,cost:{wood:3,stone:3},text:'开采铁矿与水晶'}, {id:'plank',out:4,cost:{wood:1},text:'温暖的建筑材料'}, {id:'furnace',out:1,cost:{stone:8},text:'解锁铁矿熔炼'}, {id:'iron',out:1,cost:{ore:1,wood:1},need:'furnace',text:'用原木作燃料熔炼'}, {id:'sword',out:1,cost:{iron:3,wood:2},text:'伤害 24 · 攻击距离 5'}, {id:'sigil',out:1,cost:{iron:2,crystal:3},text:'唤醒北方的星门'}, {id:'brick',out:4,cost:{stone:2},text:'坚实的遗迹风格石砖'}, {id:'torch',out:4,cost:{crystal:1,wood:1},text:'自发光的建造方块'}, {id:'food',out:3,cost:{leaf:4},text:'在叶丛里采集浆果'}];
export const quests=[['初入原野','收集 6 个原木。长按左键采集树干。'],['石器时代','采集 3 块原石，在背包中合成石镐。'],['火与金属','采集 8 块原石合成熔炉，再开采并熔炼 5 个铁锭。'],['准备远征','用 3 个铁锭与 2 个原木锻造铁剑。'],['点亮星门','在三处遗迹收集水晶，用 3 个水晶与 2 个铁锭合成符印。'],['穿越边界','前往北方星门（X 0 / Z −30），按 F 激活传送。'],['最后的守卫','击败虚空之翼。躲开红色落点，在它俯冲时挥剑。'],['原野的新生','你已完成主线。世界依然辽阔，自由建造你的故事。']];
export function hash(x,z,s=0){let n=Math.imul(x+1973,374761393)^Math.imul(z+9277,668265263)^Math.imul(s+7,1274126177);n=Math.imul(n^(n>>>13),1274126177);return ((n^(n>>>16))>>>0)/4294967295}
export function terrainHeight(x,z){const river=10*Math.sin(z*.065)-2;const d=Math.abs(x-river);const h=7+Math.sin(x*.11)*2+Math.cos(z*.12)*1.6+Math.sin((x+z)*.18)*1.1+Math.max(0,-x-17)*.25+Math.max(0,-z-28)*.1;return Math.max(2,Math.floor(h-Math.max(0,6-d)*.9));}
export class World{constructor(seed=73612){this.seed=seed;this.data=new Uint8Array(SIZE*SIZE*HEIGHT);this.edits={};this.generate()}
 index(x,y,z){return ((x+HALF)*SIZE+z+HALF)*HEIGHT+y}valid(x,y,z){return x>=-HALF&&x<HALF&&z>=-HALF&&z<HALF&&y>=0&&y<HEIGHT}get(x,y,z){return this.valid(x,y,z)?this.data[this.index(x,y,z)]:0}set(x,y,z,id,record=false){if(!this.valid(x,y,z))return false;this.data[this.index(x,y,z)]=id;if(record)this.edits[`${x},${y},${z}`]=id;return true}top(x,z){x=Math.floor(x);z=Math.floor(z);for(let y=HEIGHT-1;y>=0;y--)if(this.get(x,y,z)&&this.get(x,y,z)!==5)return y+1;return WATER}
 generate(){for(let x=-HALF;x<HALF;x++)for(let z=-HALF;z<HALF;z++){let h=terrainHeight(x,z);for(let y=0;y<=h;y++){let id=y===0?11:y===h?(h<=WATER+1?6:1):y>h-3?2:3;if(id===3&&hash(x*71+y,z,this.seed)>.952)id=7;this.set(x,y,z,id)}}
 for(let x=-HALF+3;x<HALF-3;x++)for(let z=-HALF+3;z<HALF-3;z++){const h=terrainHeight(x,z);if(h>WATER+1&&hash(x,z,this.seed)>.983&&Math.hypot(x+8,z-24)>5&&Math.hypot(x,z+30)>10){const ht=4+Math.floor(hash(z,x)*3);for(let y=h+1;y<h+ht+1;y++)this.set(x,y,z,4);for(let dx=-2;dx<=2;dx++)for(let dz=-2;dz<=2;dz++)for(let dy=-1;dy<=2;dy++)if(Math.abs(dx)+Math.abs(dz)+Math.max(0,dy)<5&&hash(x+dx,z+dz+dy*11)>.09)this.set(x+dx,h+ht+dy,z+dz,5)}}
 // Exposed quarries keep every campaign resource accessible without deep excavation.
 for(const [cx,cz] of [[-17,14],[21,8],[-27,-10]])for(let dx=-3;dx<=3;dx++)for(let dz=-3;dz<=3;dz++){const y=this.top(cx+dx,cz+dz)-1;this.set(cx+dx,y,cz+dz,hash(dx,dz,cx)>.53?7:3)}
 for(const [cx,cz] of [[-24,3],[24,-15],[-20,-30]]){let y=terrainHeight(cx,cz)+1;for(let dx=-3;dx<=3;dx++)for(let dz=-3;dz<=3;dz++)this.set(cx+dx,y,cz+dz,10);for(let dy=1;dy<=4;dy++)for(const [dx,dz] of [[-3,-3],[3,-3],[-3,3],[3,3]])this.set(cx+dx,y+dy,cz+dz,dy===4?13:10);for(let dx=-1;dx<=1;dx++)this.set(cx+dx,y+1,cz,8)}
 this.gateY=terrainHeight(0,-30)+1;for(let x=-4;x<=4;x++)for(let z=-33;z<=-27;z++){for(let y=this.gateY+1;y<HEIGHT;y++)this.set(x,y,z,0);this.set(x,this.gateY,z,10)}for(let x=-2;x<=2;x++)for(let y=1;y<=6;y++)if(Math.abs(x)===2||y===1||y===6)this.set(x,this.gateY+y,-30,12);
 }
 applyEdits(edits){for(const [key,id] of Object.entries(edits||{})){const v=key.split(',').map(Number);if(v.length===3&&v.every(Number.isInteger)&&Number.isInteger(id)&&id>=0&&id<=13)this.set(...v,id,true)}}
}
export class Progress{constructor(data={}){this.inventory={food:6,...data.inventory};this.stats={wood:0,iron:0,kills:0,...data.stats};this.stage=data.stage||0;this.dimension=data.dimension==='end'?'end':'overworld';this.won=!!data.won;this.health=Number.isFinite(data.health)?data.health:100;this.hunger=Number.isFinite(data.hunger)?data.hunger:100}
 add(id,n=1){this.inventory[id]=(this.inventory[id]||0)+n;if(id in this.stats)this.stats[id]+=n;this.advance()}
 canCraft(r){return (!r.need||this.inventory[r.need]>0)&&Object.entries(r.cost).every(([id,n])=>(this.inventory[id]||0)>=n)}
 craft(id){const r=recipes.find(r=>r.id===id);if(!r||!this.canCraft(r))return false;for(const [item,n]of Object.entries(r.cost))this.inventory[item]-=n;this.add(r.id,r.out);return true}
 advance(){const i=this.inventory;while(this.stage<7){const ok=[this.stats.wood>=6,!!i.pick,!!i.furnace&&this.stats.iron>=5,!!i.sword,!!i.sigil,this.dimension==='end',this.won][this.stage];if(!ok)break;this.stage++}}
 enter(){if(this.dimension==='end')return false;if(!this.inventory.sigil)return false;this.inventory.sigil--;this.dimension='end';this.advance();return true}
 serialize(){return {inventory:this.inventory,stats:this.stats,stage:this.stage,dimension:this.dimension,won:this.won,health:this.health,hunger:this.hunger}}
}
export function validateSave(s){if(!s||s.version!==1||!s.progress||!s.progress.inventory||typeof s.progress.inventory!=='object'||Array.isArray(s.progress.inventory)||!s.position||![s.position.x,s.position.y,s.position.z].every(Number.isFinite))throw Error('存档格式不正确');for(const [id,n] of Object.entries(s.progress.inventory))if(!Object.hasOwn(items,id)||!Number.isInteger(n)||n<0||n>999999)throw Error('存档物品数据不正确');if(!Number.isInteger(s.progress.stage)||s.progress.stage<0||s.progress.stage>7)throw Error('存档进度不正确');if(!['overworld','end'].includes(s.progress.dimension)||![s.progress.health,s.progress.hunger].every(n=>Number.isFinite(n)&&n>=0&&n<=100))throw Error('存档角色数据不正确');for(const n of Object.values(s.progress.stats||{}))if(!Number.isFinite(n)||n<0||n>10000000)throw Error('存档统计数据不正确');if(s.edits&&(typeof s.edits!=='object'||Array.isArray(s.edits)||Object.keys(s.edits).length>501760))throw Error('世界数据不正确');for(const n of [s.position.yaw,s.position.pitch])if(n!==undefined&&!Number.isFinite(n))throw Error('存档视角数据不正确');return s}
